package com.mfrp.plens.service;import com.mfrp.plens.model.*;import com.mfrp.plens.repository.*;import com.mfrp.plens.service.evaluation.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ProjectSubmissionService{private final ProjectSubmissionRepository repo;private final RuleBasedEvaluationService evaluator;public ProjectSubmissionService(ProjectSubmissionRepository r,RuleBasedEvaluationService e){repo=r;evaluator=e;}public List<ProjectSubmission> findAll(){return repo.findAll();}public ProjectSubmission create(ProjectSubmission s){evaluator.evaluate(s);return repo.save(s);}public ProjectSubmission decide(Long id,DecisionStatus status){ProjectSubmission s=repo.findById(id).orElseThrow();s.setDecisionStatus(status);return repo.save(s);}}
